// === Tab: mySketch ===
const sketch = (p) => {
    let H = 800;
    let W = 800;

    let min_width;
    let max_width;

    let G;

    let SEED;

    let N = 5;
    let CT = [];

    p.setup = () => {
        p.createCanvas(p.windowWidth, p.windowHeight);
        G = p.createGraphics(W, H);

        min_width = p.min(p.width, p.height);
        max_width = p.max(p.width, p.height);

        SEED = p.random()*998244353;

        p.randomSeed(SEED);
        p.noiseSeed(SEED);

        let bl = p.random(1);
        if(bl < .5) {G.blendMode(p.ADD);}

        for(let i=0;i<N;++i){
            CT.push(new Curtain(W/2 + (i - N*.5)/N*W+50, -100, 1, 2,
                            p.random(0.005,0.015), p.random(0.005,0.015), 
                            p.int(p.random(250, 400)), 600,
                            4,
                            p.random(-1, 1),
                            p.random(-.001,.001),
                            bl < .5 ? p.random(4, 10): p.random(25, 50)
                        )
                    )
        }


    };

    class Curtain {
        pos;
        time;

        //step width
        sx;
        sy;

        //rot
        rot;
        offset;
        rt;

        fx;
        fy;

        //num step
        nx;
        ny;

        //array
        a;
        b;

        n;

        ca;
        cb;
        cc;
        cd;

        cf1;
        cf2;

        alpha;
        constructor(x, y, sx, sy, fx, fy, nx, ny, n, rot = 0, rt = 0, alpha) {
            this.pos = p.createVector(x, y);
            this.time = 0;

            this.sx = sx;
            this.sy = sy;

            this.rot = rot;
            this.offset = x;
            this.rt = rt;

            this.fx = fx;
            this.fy = fy;

            this.nx = nx;
            this.ny = ny;

            this.n = n;
            this.a = [];
            this.b = [];

            for(let i=0;i<n;++i){
                this.a.push(p.random(-15,15));
                this.b.push(p.random(-15,15));
            }

            this.ca = [];
            this.cb = [];
            this.cc = [];
            this.cd = [];
            for(let i=0;i<3;++i){
                this.ca.push(p.random(0,.5));
                this.cb.push(p.random(.1,.4));
                this.cc.push(p.random(.5, 1.5));
                this.cd.push(p.random(1));
            }
            this.cf1 = p.random(0,2)/W;
            this.cf2 = p.random(0,2)/H;

            this.alpha = alpha;
        }

        palette(x) {
            return p.color(
                p.int(this.ca[0] + this.cb[0] * p.cos(p.TAU * (this.cc[0] * x + this.cd[0])) * 127 + 128),
                p.int(this.ca[1] + this.cb[1] * p.cos(p.TAU * (this.cc[1] * x + this.cd[1])) * 127 + 128),
                p.int(this.ca[2] + this.cb[2] * p.cos(p.TAU * (this.cc[2] * x + this.cd[2])) * 127 + 128),
                this.alpha
            );
        }
        update() {
            let y = 1;//p.sin(p.TAU*p.noise(this.pos.x/W , this.pos.y/H));
            this.pos.add(p.createVector(0,this.sy * y));
            let r = p.sin(p.TAU*p.noise(this.pos.x /W*3, this.pos.y/H*3))*.001;
            this.rot += r;
            this.time += 1;
        }
        display() {
            G.strokeWeight(4);

            G.push();

            G.translate(this.pos.x, this.pos.y);
            G.rotate(p.TAU * (this.rot));

            let prx = 0;
            let pry = 0;
            for(let j=0;j<this.n;++j){
                prx += this.a[j]*p.cos((j)*(this.pos.y)*this.fy);
                pry += this.b[j]*p.cos((j)*(this.pos.x)*this.fx);
            }
            for(let i=1;i<this.nx;++i){
                let px = 0;
                let py = 0;
                for(let j=1;j<this.n;++j){
                    px += this.a[j]*p.cos((j+1)*(this.pos.y+i*this.sx*this.time*.01)*this.fy);
                    py += this.b[j]*p.sin((j+1)*(this.pos.x+i*this.sx*this.time*.01)*this.fx);
                }
                G.stroke(
                    this.palette((this.pos.x + i*this.sx + px)*this.cf1 + (this.pos.y + py)*this.cf2)
                );
                G.line(
                    (i-1)*this.sx + prx,
                    pry,
                    i*this.sx + px,
                    py
                );
                pry = py;
                prx = px;
            }
            G.pop();
        }
    }

    p.windowResized = () => {
        p.resizeCanvas(p.windowWidth, p.windowHeight);
        min_width = p.min(p.width, p.height);
        max_width = p.max(p.width, p.height);
        p.loop();
    }

    p.draw = () => {
        p.background(30);


        for(let i=0;i<N;++i){
            CT[i].update();
            if (CT[i].time < CT[i].ny) {
                CT[i].display();
            }
        }

        p.image(G, (p.width-min_width)/2, (p.height-min_width)/2, min_width, min_width, 0, 0, W, H);
    };


    p.keyPressed = () => {
        if(p.key == 's') {
            G.save("image.png");
        }
    }

};

new p5(sketch);

